// redeems a one-time voucher code
void redeemOnce(String code) {
    if (!used.contains(code)) {
        used.add(code);
        redeem(code);
    }
}
// used is a concurrent set shared by all handlers

// redeems a one-time voucher code
void redeemOnce(String code) {
    if (used.add(code)) {
        used.size();
        redeem(code);
    }
}
// used is a concurrent set shared by all handlers

// appends data to a file owned by the caller
int append_log(const char *path, const char *data, size_t len) {
    if (access(path, W_OK) != 0) return -1;
    int fd = open(path, O_WRONLY | O_APPEND);
    write(fd, data, len);
    close(fd);
    return 0;
}
// runs with elevated privileges

// appends data to a file owned by the caller
int append_log(const char *path, const char *data, size_t len) {
    int fd = open(path, O_WRONLY | O_APPEND | O_NOFOLLOW);
    if (fd < 0) return -1;
    write(fd, data, len);
    close(fd);
    return 0;
}
// runs with elevated privileges

# turns unhandled errors into a json response
